// OpenStreetMap community listings, not verified menus or live inventory.
const endpoint='https://overpass-api.de/api/interpreter';
const cache=new Map();
export function distanceMiles(a,b){const r=Math.PI/180,dlat=(b.latitude-a.latitude)*r,dlon=(b.longitude-a.longitude)*r;const h=Math.sin(dlat/2)**2+Math.cos(a.latitude*r)*Math.cos(b.latitude*r)*Math.sin(dlon/2)**2;return 3958.7613*2*Math.atan2(Math.sqrt(h),Math.sqrt(Math.max(0,1-h)))}
export function safeUrl(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:null}catch{return null}}
export function normalizePlaces(elements,origin){const seen=new Set();return elements.flatMap(e=>{const t=e.tags||{},latitude=e.lat??e.center?.lat,longitude=e.lon??e.center?.lon;if(!t.name||!Number.isFinite(latitude)||!Number.isFinite(longitude)||t['drink:coffee']==='no'||t.disused==='yes'||t.access==='private')return [];const key=t.name.toLowerCase()+latitude.toFixed(4)+longitude.toFixed(4);if(seen.has(key))return [];seen.add(key);return [{id:`${e.type}/${e.id}`,name:t.name,latitude,longitude,distance:distanceMiles(origin,{latitude,longitude}),website:safeUrl(t.website||t['contact:website']),menu:safeUrl(t['website:menu']),address:[t['addr:housenumber'],t['addr:street'],t['addr:city']].filter(Boolean).join(' '),checked:t['check_date:menu']||null,listedDrinks:['espresso','cappuccino','latte','filter_coffee'].filter(k=>['yes','served','takeaway'].includes(t[`drink:${k}`])).map(k=>k.replaceAll('_',' ')),source:`https://www.openstreetmap.org/${e.type}/${e.id}`}]}).sort((a,b)=>a.distance-b.distance)}
export async function findNearby(origin,{radius=8000,signal}={}){if(!Number.isFinite(origin.latitude)||!Number.isFinite(origin.longitude)||Math.abs(origin.latitude)>90||Math.abs(origin.longitude)>180)throw new Error('Invalid location');const lat=origin.latitude.toFixed(3),lon=origin.longitude.toFixed(3),key=`${lat},${lon},${radius}`;const hit=cache.get(key);if(hit&&Date.now()-hit.time<300000)return {...hit.result,places:normalizePlaces(hit.elements,origin)};const query=`[out:json][timeout:20];(nwr["amenity"="cafe"](around:${radius},${lat},${lon});nwr["cuisine"="coffee_shop"](around:${radius},${lat},${lon}););out center tags;`;const response=await fetch(endpoint,{method:'POST',body:new URLSearchParams({data:query}),signal});if(!response.ok)throw new Error(`Café lookup unavailable (${response.status})`);const data=await response.json();if(!Array.isArray(data.elements)||data.remark)throw new Error('Incomplete café lookup');const result={places:normalizePlaces(data.elements,origin),fetchedAt:new Date().toISOString(),radius};cache.set(key,{result,elements:data.elements,time:Date.now()});return result}
